18	var (
19		errMemoCreatorNotFound     = stderrors.New("memo creator not found")
20		errReactionCreatorNotFound = stderrors.New("reaction creator not found")
21	)
22	
23	func (s *APIV1Service) convertMemoFromStore(ctx context.Context, memo *store.Memo, reactions []*store.Reaction, attachments []*store.Attachment, relations []*v1pb.MemoRelation) (*v1pb.Memo, error) {
24		creatorMap, err := s.listUsersByID(ctx, []int32{memo.CreatorID})
25		if err != nil {
26			return nil, errors.Wrap(err, "failed to list memo creators")
27		}
28		return s.convertMemoFromStoreWithCreators(ctx, memo, reactions, attachments, relations, creatorMap)
29	}
30	
31	func (s *APIV1Service) convertMemoFromStoreWithCreators(ctx context.Context, memo *store.Memo, reactions []*store.Reaction, attachments []*store.Attachment, relations []*v1pb.MemoRelation, creatorMap map[int32]*store.User) (*v1pb.Memo, error) {
32		name := fmt.Sprintf("%s%s", MemoNamePrefix, memo.UID)
33		creator := creatorMap[memo.CreatorID]
34		if creator == nil {
35			return nil, errMemoCreatorNotFound
36		}
37		memoMessage := &v1pb.Memo{
38			Name:       name,
39			State:      convertStateFromStore(memo.RowStatus),
40			Creator:    BuildUserName(creator.Username),
41			CreateTime: timestamppb.New(time.Unix(memo.CreatedTs, 0)),
42			UpdateTime: timestamppb.New(time.Unix(memo.UpdatedTs, 0)),
43			Content:    memo.Content,
44			Visibility: convertVisibilityFromStore(memo.Visibility),
45			Pinned:     memo.Pinned,
46		}
47		if memo.Payload != nil {
48			memoMessage.Tags = memo.Payload.Tags
49			memoMessage.Property = convertMemoPropertyFromStore(memo.Payload.Property)
50			memoMessage.Location = convertLocationFromStore(memo.Payload.Location)
51		}
52	
53		if memo.ParentUID != nil {
54			parentName := fmt.Sprintf("%s%s", MemoNamePrefix, *memo.ParentUID)
55			memoMessage.Parent = &parentName
56		}
57	
58		reactionMessages, err := s.convertReactionsFromStoreWithCreators(ctx, reactions, creatorMap)
59		if err != nil {
60			return nil, errors.Wrap(err, "failed to convert reactions")
61		}
62		memoMessage.Reactions = reactionMessages
63	
64		if relations != nil {
65			memoMessage.Relations = relations
66		} else {
67			memoMessage.Relations = []*v1pb.MemoRelation{}
68		}
69	
70		memoMessage.Attachments = []*v1pb.Attachment{}
71		for _, attachment := range attachments {
72			attachmentResponse := convertAttachmentFromStore(attachment)
73			memoMessage.Attachments = append(memoMessage.Attachments, attachmentResponse)
74		}
75	
76		snippet, err := s.getMemoContentSnippet(memo.Content)
77		if err != nil {
78			return nil, errors.Wrap(err, "failed to get memo content snippet")
79		}
80		memoMessage.Snippet = snippet
81	
82		return memoMessage, nil
83	}
