155	func convertReactionFromStoreWithCreators(reaction *store.Reaction, creatorsByID map[int32]*store.User) (*v1pb.Reaction, error) {
156		creator := creatorsByID[reaction.CreatorID]
157		if creator == nil {
158			return nil, errReactionCreatorNotFound
159		}
160	
161		reactionUID := fmt.Sprintf("%d", reaction.ID)
162		return &v1pb.Reaction{
163			Name:         fmt.Sprintf("%s/%s%s", reaction.ContentID, ReactionNamePrefix, reactionUID),
164			Creator:      BuildUserName(creator.Username),
165			ContentId:    reaction.ContentID,
166			ReactionType: reaction.ReactionType,
167			CreateTime:   timestamppb.New(time.Unix(reaction.CreatedTs, 0)),
168		}, nil
169	}
