9	/** Distance from the viewport top of the "reading line" used to decide the active section. */
10	const READING_LINE_OFFSET = 100;
11	
12	/** Outline navigation for memo headings (h1–h4) with active-section tracking. */
13	const MemoOutline = ({ headings }: MemoOutlineProps) => {
14	  const [activeSlug, setActiveSlug] = useState<string | null>(null);
15	  const rafRef = useRef(0);
16	
17	  const minLevel = useMemo(() => Math.min(...headings.map((heading) => heading.level)), [headings]);
18	
19	  useEffect(() => {
20	    const update = () => {
21	      rafRef.current = 0;
22	      let current: string | null = null;
23	      for (const heading of headings) {
24	        const el = document.getElementById(heading.slug);
25	        if (!el) continue;
26	        if (el.getBoundingClientRect().top > READING_LINE_OFFSET) break;
27	        current = heading.slug;
28	      }
29	      setActiveSlug(current ?? headings[0]?.slug ?? null);
30	    };
31	    const requestUpdate = () => {
32	      if (!rafRef.current) {
33	        rafRef.current = requestAnimationFrame(update);
34	      }
35	    };
36	    update();
37	    // Capture-phase listener so scrolls of any nested container are observed too.
38	    window.addEventListener("scroll", requestUpdate, true);
39	    window.addEventListener("resize", requestUpdate);
40	    return () => {
41	      window.removeEventListener("scroll", requestUpdate, true);
42	      window.removeEventListener("resize", requestUpdate);
43	      if (rafRef.current) {
44	        cancelAnimationFrame(rafRef.current);
45	      }
46	    };
47	  }, [headings]);
48	
49	  const handleClick = (e: React.MouseEvent<HTMLAnchorElement>, slug: string) => {
50	    e.preventDefault();
51	    const el = document.getElementById(slug);
52	    if (el) {
53	      setActiveSlug(slug);
54	      el.scrollIntoView({ behavior: "smooth", block: "start" });
55	      window.history.replaceState(null, "", `#${slug}`);
56	    }
57	  };
58	
59	  return (
60	    <nav className="relative flex flex-col">
61	      {headings.map((heading, index) => {
62	        const active = heading.slug === activeSlug;
63	        return (
64	          <a
65	            key={`${heading.slug}-${index}`}
66	            href={`#${heading.slug}`}
67	            onClick={(e) => handleClick(e, heading.slug)}
68	            aria-current={active ? "location" : undefined}
69	            className={cn(
70	              "relative block truncate rounded-md py-[3px] pr-1.5 -mx-1.5 text-[13px] leading-5 transition-colors",
71	              heading.level === minLevel && "font-medium",
72	              active ? "text-foreground" : "text-muted-foreground/70 hover:bg-accent hover:text-foreground",
73	            )}
74	            style={{ paddingLeft: 14 + (heading.level - minLevel) * 12 }}
75	          >
76	            <span
77	              className={cn(
78	                "absolute left-1.5 top-1/2 h-[13px] w-[2px] -translate-y-1/2 rounded-full transition-colors",
79	                active ? "bg-primary" : "bg-border",
80	              )}
81	            />
82	            {heading.text}
83	          </a>
84	        );
85	      })}
86	    </nav>
87	  );
88	};
